svg.script:
'use strict';
(function(){
// ===== helpers =====
const NS='http://www.w3.org/2000/svg', INK='#3b2a2a';
const TS=64, GW=14, GH=8, OX=192, OY=150;
const RED='#e8483b', YEL='#ffd35c', MINT='#5fd3a8', SKY='#6cc4f0', CREAM='#fff3dc', PAPER='#fffaf0';
const P1C='#e8483b', P2C='#3d8fd6';
const $=id=>document.getElementById(id);
const root=$('root');
function E(tag,a,p){const e=document.createElementNS(NS,tag); if(a) for(const k in a) e.setAttribute(k,a[k]); if(p) p.appendChild(e); return e;}
function T(s,a,p){const e=E('text',a,p); e.textContent=s; if(a&&/\bo\b/.test(a.class||'')&&!a.stroke) e.setAttribute('stroke',INK); return e;}
function U(id,s,a,p){const e=E('use',{href:'#'+id,x:-s/2,y:-s/2,width:s,height:s},p); if(a) for(const k in a) e.setAttribute(k,a[k]); return e;}
function Gp(x,y,p,a){const g=E('g',a||{},p); if(x||y) g.setAttribute('transform','translate('+x+','+y+')'); return g;}
function clear(e){while(e.firstChild) e.removeChild(e.firstChild);}
function show(e,on){e.style.display=on?'':'none';}
function mv(e,x,y,s,r){e.setAttribute('transform','translate('+x.toFixed(1)+','+y.toFixed(1)+')'+(r?' rotate('+r.toFixed(2)+')':'')+(s!=null&&s!==1?' scale('+s.toFixed(3)+')':''));}
function mv2(e,x,y,sx,sy){e.setAttribute('transform','translate('+x.toFixed(1)+','+y.toFixed(1)+') scale('+sx.toFixed(3)+','+sy.toFixed(3)+')');}
const clamp=(v,a,b)=>v<a?a:v>b?b:v, lerp=(a,b,t)=>a+(b-a)*t, rnd=(a,b)=>a+Math.random()*(b-a);
const easeOutBack=t=>{const c=1.9; t=clamp(t,0,1)-1; return 1+(c+1)*t*t*t+c*t*t;};
function rrect(x,y,w,h,r,a,p){return E('rect',Object.assign({x,y,width:w,height:h,rx:r},a||{}),p);}
function fmtTime(s){s=Math.max(0,Math.ceil(s)); return Math.floor(s/60)+':'+String(s%60).padStart(2,'0');}

// ===== audio =====
const AU={ctx:null,master:null,sfxG:null,musG:null,muted:false,nb:null,next:0,step:0,music:false};
function auInit(){
  try{
    if(!AU.ctx){
      const C=window.AudioContext||window.webkitAudioContext; if(!C) return;
      const c=new C(); AU.ctx=c;
      AU.master=c.createGain(); AU.master.gain.value=AU.muted?0:0.7; AU.master.connect(c.destination);
      AU.sfxG=c.createGain(); AU.sfxG.gain.value=0.9; AU.sfxG.connect(AU.master);
      AU.musG=c.createGain(); AU.musG.gain.value=0.3; AU.musG.connect(AU.master);
      const n=c.sampleRate, b=c.createBuffer(1,n,n), d=b.getChannelData(0);
      for(let i=0;i<n;i++) d[i]=Math.random()*2-1;
      AU.nb=b;
    }
    if(AU.ctx.state==='suspended') AU.ctx.resume();
  }catch(e){}
}
function tone(f,d,type,vol,t0,f2,dest){
  try{
    const c=AU.ctx; if(!c) return;
    const t=c.currentTime+(t0||0), o=c.createOscillator(), g=c.createGain();
    o.type=type||'sine'; o.frequency.setValueAtTime(f,t);
    if(f2) o.frequency.exponentialRampToValueAtTime(f2,t+d);
    g.gain.setValueAtTime(0.0001,t); g.gain.exponentialRampToValueAtTime(vol||0.2,t+0.008);
    g.gain.exponentialRampToValueAtTime(0.0001,t+d);
    o.connect(g); g.connect(dest||AU.sfxG); o.start(t); o.stop(t+d+0.03);
  }catch(e){}
}
function noise(d,vol,freq,type,t0,q,dest){
  try{
    const c=AU.ctx; if(!c||!AU.nb) return;
    const t=c.currentTime+(t0||0), s=c.createBufferSource(), f=c.createBiquadFilter(), g=c.createGain();
    s.buffer=AU.nb; f.type=type||'bandpass'; f.frequency.value=freq||1000; f.Q.value=q||1;
    g.gain.setValueAtTime(vol||0.2,t); g.gain.exponentialRampToValueAtTime(0.0001,t+d);
    s.connect(f); f.connect(g); g.connect(dest||AU.sfxG); s.start(t,Math.random()*0.5); s.stop(t+d+0.03);
  }catch(e){}
}
const SFX={
  pick(){tone(520,0.08,'triangle',0.18,0,800);},
  place(){tone(300,0.09,'triangle',0.2,0,170); noise(0.05,0.08,900);},
  plate(){tone(1500,0.12,'sine',0.1); tone(2250,0.1,'sine',0.05,0.015);},
  chop(){noise(0.05,0.35,2600,'bandpass',0,2.2); tone(190,0.05,'square',0.05,0,90);},
  done(){tone(660,0.08,'triangle',0.16); tone(990,0.15,'triangle',0.16,0.07);},
  bonk(){tone(170,0.1,'square',0.07,0,110);},
  trash(){noise(0.25,0.22,500,'lowpass'); tone(210,0.2,'triangle',0.12,0,70);},
  ding(){tone(1568,1.1,'sine',0.22); tone(2093,0.9,'sine',0.12); tone(3136,0.5,'sine',0.04);},
  coin(){tone(988,0.05,'square',0.05); tone(1319,0.12,'square',0.05,0.045);},
  buzz(){tone(140,0.3,'sawtooth',0.1,0,110); tone(147,0.3,'sawtooth',0.08);},
  warn(){tone(1150,0.07,'square',0.06);},
  burnt(){noise(0.6,0.28,700,'lowpass'); tone(220,0.5,'sawtooth',0.07,0,90);},
  sizzle(){noise(0.16,0.045,5200,'highpass');},
  bubble(){tone(rnd(300,500),0.06,'sine',0.05,0,rnd(700,900));},
  dash(){noise(0.18,0.16,1200,'bandpass',0,0.8);},
  order(){tone(740,0.07,'triangle',0.13); tone(988,0.1,'triangle',0.13,0.07);},
  expire(){tone(392,0.18,'triangle',0.15); tone(330,0.18,'triangle',0.15,0.16); tone(262,0.35,'triangle',0.15,0.32);},
  tick(){tone(1800,0.03,'square',0.05);},
  beep(){tone(660,0.16,'square',0.09);},
  go(){tone(880,0.12,'square',0.09); tone(1320,0.32,'square',0.09,0.1);},
  star(){[1047,1319,1568,2093].forEach((f,i)=>tone(f,0.25,'triangle',0.11,i*0.06));},
  click(){tone(900,0.04,'triangle',0.12);},
  swap(){tone(500,0.07,'triangle',0.12,0,950);},
  bump(){tone(120,0.12,'sine',0.14,0,70); noise(0.06,0.08,400,'lowpass');},
  fanfare(){[523,659,784,1047].forEach((f,i)=>tone(f,0.3,'triangle',0.13,i*0.12)); tone(1047,0.9,'triangle',0.11,0.5); tone(1319,0.9,'triangle',0.08,0.5);}
};
function sfx(n){ if(!AU.ctx||AU.muted) return; try{ SFX[n]&&SFX[n](); }catch(e){} }
// music: tiny 8th-note sequencer scheduled ahead on the audio clock
const MEL=[72,0,76,79,0,76,72,0, 74,0,77,81,0,77,74,0, 72,0,76,79,84,0,79,76, 77,0,74,71,72,0,0,0];
const BAS=[48,0,55,0,48,0,55,0, 50,0,57,0,50,0,57,0, 45,0,52,0,45,0,52,0, 43,0,50,0,48,0,43,0];
const mtof=m=>440*Math.pow(2,(m-69)/12);
function musicTick(){
  const c=AU.ctx; if(!c||!AU.music||AU.muted) return;
  const step=(G.time<20?0.2:0.25);
  if(AU.next<c.currentTime) AU.next=c.currentTime+0.05;
  while(AU.next<c.currentTime+0.2){
    const i=AU.step%32, t0=AU.next-c.currentTime;
    if(MEL[i]) tone(mtof(MEL[i]),step*0.85,'triangle',0.075,t0,null,AU.musG);
    if(BAS[i]) tone(mtof(BAS[i]),step*1.7,'sine',0.15,t0,null,AU.musG);
    if(i%2===1) noise(0.025,0.03,7000,'highpass',t0,1,AU.musG);
    AU.next+=step; AU.step++;
  }
}
function setMute(m){
  AU.muted=m;
  try{ if(AU.master) AU.master.gain.value=m?0:0.7; }catch(e){}
  if(UI.muteX) show(UI.muteX,m);
  if(UI.muteW) show(UI.muteW,!m);
}

// ===== levels & recipes =====
const RECIPES={
  soup:{name:'番茄汤',en:'TOMATO SOUP',parts:['soup'],icon:'i-soup',reward:20,time:66,band:'#ffb067',ing:['i-tomC','i-tomC','i-tomC','i-pot']},
  salad:{name:'蔬菜沙拉',en:'GARDEN SALAD',parts:['letC','tomC'],icon:'i-salad',reward:16,time:50,band:MINT,ing:['i-letC','i-tomC']},
  burger:{name:'汉堡',en:'BURGER',parts:['bun','patty','letC'],icon:'i-burger',reward:26,time:76,band:YEL,ing:['i-bun','i-pat','i-letC','i-pan']}
};
const PART_ICON={soup:'i-soup',tomC:'i-tomC',letC:'i-letC',bun:'i-bun',patty:'i-pat'};
const LEVELS=[
  {diff:'简单',name:'街角小馆',en:'CORNER BISTRO',tag:MINT,recipes:['soup','salad'],maxOrders:3,interval:17,timeMul:1.35,
   cook:7,burn:10,patty:6,pburn:9,chop:1.2,tip:8,penalty:5,stars:[50,120,190],cart:false,
   map:['#TT##CC##SS###',
        '#............W',
        'L..1.........W',
        'L....####....#',
        '#....####....#',
        '#.........2..#',
        '#............#',
        '#XPP####CC####']},
  {diff:'普通',name:'汉堡快餐',en:'BURGER JOINT',tag:YEL,recipes:['salad','burger'],maxOrders:4,interval:15,timeMul:1.15,
   cook:7,burn:8,patty:6,pburn:7,chop:1.3,tip:10,penalty:8,stars:[60,140,220],cart:false,
   map:['#LL#CC##CC#FF#',
        'T............W',
        'T..1.........W',
        '#...##..##...#',
        'M...##..##...#',
        'M.........2..#',
        '#............#',
        '#XPP##BB###F##']},
  {diff:'困难',name:'忙碌后厨',en:'BUSY BACKLINE',tag:RED,recipes:['soup','salad','burger'],maxOrders:5,interval:12.5,timeMul:1.0,
   cook:7,burn:6,patty:6,pburn:5.5,chop:1.4,tip:12,penalty:10,stars:[60,140,230],cart:true,cartRow:4,
   map:['#TTLL##SS#FF##',
        'C.....=......W',
        'C.1...=......W',
        '#.....=...2..#',
        '#............M',
        'P.....=......M',
        'P.....=......#',
        '#X#CC##BBC#X##']}
];
const ROUND=150;
const CRATE={T:'tom',L:'let',M:'meat',B:'bun'};

// ===== state =====
const G={state:'title',sel:0,mode:1,lvl:LEVELS[0],li:0,tiles:[],chefs:[],active:0,orders:[],score:0,shown:0,time:ROUND,
  stats:null,nextOrder:0,cart:null,speed:1,t:0,shake:0,cd:0,overT:0,starsLit:0,newBest:false,helpFrom:'title',lastTick:0,
  containers:[],items:new Set(),botOn:0,freeze:false,orderSeq:0};
const UI={};
let UID=1;
function mkItem(t,o){return Object.assign({id:UID++,t,ch:false,prog:0,parts:[],n:0,cook:0,over:0,burnt:false,meat:false,view:null,dirty:true,refs:null,warnT:0},o||{});}
function subset(a,b){const c={}; b.forEach(x=>{c[x]=(c[x]||0)+1;}); for(const x of a){ if(!c[x]) return false; c[x]--; } return true;}
function sameSet(a,b){return a.length===b.length&&subset(a,b);}
function recipeOf(parts){ for(const k in RECIPES) if(sameSet(parts,RECIPES[k].parts)) return k; return null; }
function plateAccepts(parts,add){ const np=parts.concat([add]); return G.lvl.recipes.some(r=>subset(np,RECIPES[r].parts)); }
function partOf(it){
  if(!it) return null;
  if(it.t==='tom'&&it.ch) return 'tomC';
  if(it.t==='let'&&it.ch) return 'letC';
  if(it.t==='bun') return 'bun';
  return null;
}
const potReady=p=>p.t==='pot'&&p.n>=3&&p.cook>=1&&!p.burnt;
const panReady=p=>p.t==='pan'&&p.meat&&p.cook>=1&&!p.burnt;
function tileAt(c,r){ return (c<0||r<0||c>=GW||r>=GH)?null:G.tiles[r*GW+c]; }
function tileAtPx(x,y){ return tileAt(Math.floor((x-OX)/TS),Math.floor((y-OY)/TS)); }
function loadBest(k){ try{ const v=localStorage.getItem('opus_showcase_kitchen-rush_best'+(k==null?'':'_k'+k)); return v?(parseInt(v,10)||0):0; }catch(e){ return 0; } }
function saveBest(k,v){ try{ localStorage.setItem('opus_showcase_kitchen-rush_best'+(k==null?'':'_k'+k),String(v)); }catch(e){} }

// ===== kitchen build =====
const L={stat:$('kStatic'),fx:$('kFx'),hi:$('kHi'),items:$('kItems'),actors:$('kActors'),part:$('kPart'),pop:$('kPop'),world:$('world')};
function buildKitchen(li){
  G.li=li; G.lvl=LEVELS[li];
  clear(L.stat); clear(L.fx); clear(L.items); clear(L.hi);
  G.items.clear(); G.containers=[]; G.tiles=[]; G.bouncing=[]; G.spawns=[];
  const map=G.lvl.map;
  for(let r=0;r<GH;r++) for(let c=0;c<GW;c++){
    let k=map[r][c];
    if(k==='1'||k==='2'){ G.spawns[+k-1]=[c,r]; k='.'; }
    const x=OX+c*TS, y=OY+r*TS;
    G.tiles.push({c,r,k,solid:k!=='.',x,y,cx:x+32,cy:y+26,th:50,item:null,fx:{}});
  }
  rrect(OX-22,OY-10,GW*TS+44,GH*TS+46,28,{fill:INK,opacity:.3},L.stat);
  rrect(OX-22,OY-24,GW*TS+44,GH*TS+50,28,{fill:'#8a5234',stroke:INK,'stroke-width':5},L.stat);
  rrect(OX-11,OY-13,GW*TS+22,GH*TS+28,16,{fill:'#6a3c24'},L.stat);
  E('rect',{x:OX,y:OY,width:GW*TS,height:GH*TS,fill:'url(#p-floor)'},L.stat);
  for(const t of G.tiles){
    const n=tileAt(t.c,t.r-1);
    if(!t.solid&&n&&n.solid) E('rect',{x:t.x,y:t.y,width:64,height:9,fill:INK,opacity:.1},L.stat);
  }
  for(const t of G.tiles) if(t.solid) drawTile(t);
  for(const t of G.tiles){
    if(t.k==='S') placeItem(t,mkItem('pot'),true);
    if(t.k==='F') placeItem(t,mkItem('pan'),true);
  }
  G.hi=[0,1].map(i=>{
    const g=E('g',{class:'np'},L.hi);
    rrect(-30,-30,60,60,10,{fill:'#fff',opacity:.22},g);
    rrect(-30,-30,60,60,10,{fill:'none',stroke:'#fff','stroke-width':4},g);
    rrect(-30,-30,60,60,10,{fill:'none',stroke:i?P2C:P1C,'stroke-width':2,'stroke-dasharray':'8 6'},g);
    show(g,false); return g;
  });
  buildCart();
}
function drawTile(t){
  const {x,y,k}=t, s=tileAt(t.c,t.r+1), front=!s||!s.solid, th=front?50:64;
  t.th=th; t.cy=y+(front?24:30);
  const g=E('g',{},L.stat), sw={stroke:INK,'stroke-width':3,'stroke-linejoin':'round'};
  let top='url(#p-wood)', fr='#b8733f';
  if(k==='='){top='url(#g-steel)'; fr='#8d9aa6';}
  else if(k==='S'||k==='F'){top='url(#g-stove)'; fr='#4f5a66';}
  else if(k==='W'){top=MINT; fr='#36a07a';}
  E('rect',Object.assign({x,y,width:64,height:th,fill:top},sw),g);
  if(front){
    E('rect',Object.assign({x,y:y+th,width:64,height:14,fill:fr},sw),g);
    E('rect',{x:x+3,y:y+th+2,width:58,height:2.5,fill:'#fff',opacity:.18},g);
  }
  const cx=x+32, cy=y+th/2;
  if(k==='='){
    E('rect',{x:x+3,y:cy-3,width:58,height:6,fill:RED,opacity:.8},g);
    E('path',{d:`M${x+10},${cy} l9,-7 v14z M${x+54},${cy} l-9,-7 v14z`,fill:INK,opacity:.45},g);
  } else if(CRATE[k]){
    rrect(x+5,y+4,54,th-8,6,Object.assign({fill:'url(#p-crate)'},sw),g);
    rrect(x+11,y+10,42,th-20,4,{fill:'#6f4024'},g);
    const ic={T:'i-tom',L:'i-let',M:'i-meat',B:'i-bun'}[k], gi=Gp(cx,cy+1,g);
    U(ic,22,{x:-22,y:-15},gi); U(ic,22,{x:0,y:-14},gi); U(ic,26,{x:-13,y:-9},gi);
    if(front) rrect(x+18,y+th+2,28,10,3,{fill:{T:RED,L:'#7cc943',M:'#e8676b',B:'#f4b95e'}[k],stroke:INK,'stroke-width':2},g);
  } else if(k==='C'){
    const b=Gp(cx,cy,g);
    rrect(-25,-17,50,34,8,{fill:'#c98d52',stroke:INK,'stroke-width':3},b);
    rrect(-22,-15,44,28,6,{fill:'#f7dcae'},b);
    E('circle',{cx:18,cy:-9,r:3,fill:'#c98d52'},b);
    t.fx.knife=Gp(x+46,cy+9,L.fx); U('i-knife',30,null,t.fx.knife);
    const bar=Gp(cx,y-6,L.pop,{class:'np'});
    rrect(-27,-8,54,16,8,{fill:'#fff',stroke:INK,'stroke-width':3},bar);
    t.fx.fill=rrect(-23,-4,46,8,4,{fill:MINT},bar);
    show(bar,false); t.fx.bar=bar;
  } else if(k==='S'||k==='F'){
    t.fx.glow=E('circle',{cx,cy,r:32,fill:'url(#g-glow)'},L.fx); show(t.fx.glow,false);
    const b=Gp(cx,cy,g);
    E('circle',{r:22,fill:'#373e47',stroke:INK,'stroke-width':3},b);
    E('circle',{r:14,fill:'none',stroke:'#5f6a76','stroke-width':3},b);
    E('path',{d:'M-22,0 L22,0 M0,-22 L0,22',stroke:'#2a3038','stroke-width':3},b);
    if(front){ E('circle',{cx:x+18,cy:y+th+7,r:3.6,fill:'#eee',stroke:INK,'stroke-width':2},g); E('circle',{cx:x+46,cy:y+th+7,r:3.6,fill:'#eee',stroke:INK,'stroke-width':2},g); }
  } else if(k==='P'){
    for(let i=0;i<3;i++) U('i-plate',44,null,Gp(cx,cy+7-i*6,g));
  } else if(k==='W'){
    rrect(x+6,y+6,52,th-12,8,{fill:'#a6efd2',stroke:INK,'stroke-width':2.5},g);
    E('path',{d:`M${x+19},${cy-8} l8,8 l-8,8 M${x+33},${cy-8} l8,8 l-8,8`,fill:'none',stroke:'#fff','stroke-width':5,'stroke-linecap':'round','stroke-linejoin':'round'},g);
    const n=tileAt(t.c,t.r-1);
    if(!n||n.k!=='W'){
      U('i-bell',30,null,Gp(x+50,y+8,g));
      const sg=Gp(x+64+13,y+th,g);
      rrect(-11,-34,22,68,8,{fill:YEL,stroke:INK,'stroke-width':3},sg);
      T('出',{x:0,y:-8,class:'m','font-size':16},sg); T('餐',{x:0,y:15,class:'m','font-size':16},sg);
    }
  } else if(k==='X'){
    const b=Gp(cx,cy,g);
    E('circle',{r:21,fill:'#5c6a76',stroke:INK,'stroke-width':3.5},b);
    E('circle',{r:14,fill:'#2a3239'},b);
    E('path',{d:'M-6,-4 L6,4 M6,-4 L-6,4',stroke:'#56616b','stroke-width':3,'stroke-linecap':'round'},b);
  }
}
function buildCart(){
  if(G.cart&&G.cart.g&&G.cart.g.parentNode) G.cart.g.parentNode.removeChild(G.cart.g);
  G.cart=null;
  if(!G.lvl.cart) return;
  const r=G.lvl.cartRow, y=OY+r*TS+32;
  const g=E('g',{},L.actors), b=E('g',{},g);
  E('ellipse',{cx:0,cy:24,rx:30,ry:7,fill:INK,opacity:.2},b);
  U('i-cart',62,{y:-33},b);
  for(let i=0;i<3;i++) U('i-plate',34,null,Gp(-10+i*2,-10-i*5,b));
  U('i-pot',26,null,Gp(14,-14,b));
  const sgn=Gp(0,-40,b); rrect(-19,-11,38,20,6,{fill:YEL,stroke:INK,'stroke-width':3},sgn); T('小心',{x:0,y:5,class:'m','font-size':12},sgn);
  G.cart={x:OX+1*TS+32,y,dir:1,spd:78,wait:0.6,minX:OX+1*TS+32,maxX:OX+12*TS+32,g,b,hw:28,hh:22,bumpT:0};
}

// ===== items =====
function ensureView(it){
  if(!it.view) it.view=E('g',{class:'np'});
  if(it.dirty){ it.dirty=false; rebuildView(it); }
  return it.view;
}
function rebuildView(it){
  const g=it.view; clear(g); it.refs=null;
  if(it.t!=='plate') E('ellipse',{cx:0,cy:12,rx:18,ry:5,fill:INK,opacity:.16},g);
  if(it.t==='tom') U(it.ch?'i-tomC':'i-tom',40,null,g);
  else if(it.t==='let') U(it.ch?'i-letC':'i-let',40,null,g);
  else if(it.t==='meat') U(it.ch?'i-patR':'i-meat',40,null,g);
  else if(it.t==='bun') U('i-bun',38,null,g);
