}
const PLACE=[[],[[0,-6]],[[-9,-5],[9,-6]],[[-10,-3],[10,-4],[0,-12]]];
function plateView(it,g){
  E('ellipse',{cx:0,cy:12,rx:24,ry:6,fill:INK,opacity:.16},g);
  U('i-plate',52,null,g);
  const n=it.parts.length; if(!n) return;
  const r=recipeOf(it.parts);
