  it.parts.forEach((p,i)=>{ const q=PLACE[Math.min(n,3)][i]||[0,-6]; U(PART_ICON[p],26,null,Gp(q[0],q[1],g)); });
  it.parts.forEach((p,i)=>{
    const b=Gp((i-(n-1)/2)*23,-40,g);
