    else if(it.n>=3){ E('ellipse',{cx:0,cy:-8,rx:18,ry:6,fill:'#f39478'},g); E('circle',{cx:-6,cy:-9,r:2.4,fill:'#ffd0c0'},g); E('circle',{cx:6,cy:-7,r:1.8,fill:'#ffd0c0'},g); }
    else [[-8,-8],[8,-8],[0,-11]].slice(0,it.n).forEach(q=>E('circle',{cx:q[0],cy:q[1],r:5.5,fill:RED,stroke:INK,'stroke-width':2},g));
  }
  if(it.n>0){ const b=Gp(-26,-24,g); E('circle',{r:9,fill:'#fff',stroke:INK,'stroke-width':2.2},b); T(it.n+'/3',{x:0,y:3.5,class:'m','font-size':9},b); if(it.n>=3||it.burnt) show(b,false); }
