function placeItem(t,it,quiet){
  t.item=it; it.where=t; G.items.add(it);
  if((it.t==='pot'||it.t==='pan')&&G.containers.indexOf(it)<0) G.containers.push(it);
  ensureView(it); L.items.appendChild(it.view); mv(it.view,t.cx,t.cy);
  if(!quiet) G.bouncing.push({it,t:0,x:t.cx,y:t.cy});
}
function takeItem(t){ const it=t.item; t.item=null; return it; }
function destroyItem(it){
  if(it.view&&it.view.parentNode) it.view.parentNode.removeChild(it.view);
  G.items.delete(it); const i=G.containers.indexOf(it); if(i>=0) G.containers.splice(i,1);
