  it.where=null;
}
function itemPos(it){
  const w=it.where; if(!w) return [0,0];
  if(w.held===it) return [w.x+w.fx*12,w.y-40];
  return [w.cx,w.cy];
}

// ===== chefs =====
const CR=20;
function buildChef(i){
  const col=i?P2C:P1C, sw={stroke:INK,'stroke-width':3.5};
  const g=E('g',{},L.actors);
  E('ellipse',{cx:0,cy:0,rx:22,ry:8,fill:INK,opacity:.2},g);
  const ring=E('ellipse',{cx:0,cy:0,rx:27,ry:11,fill:'none',stroke:col,'stroke-width':4,'stroke-dasharray':'10 6'},g);
  const b=E('g',{},g);
  const footL=E('ellipse',{cx:-9,cy:-3,rx:7,ry:5,fill:INK},b), footR=E('ellipse',{cx:9,cy:-3,rx:7,ry:5,fill:INK},b);
  const back=E('g',{},b);
  E('ellipse',Object.assign({cx:0,cy:-22,rx:20,ry:18,fill:'#fffdf8'},sw),b);
  E('circle',{cx:-6,cy:-22,r:2,fill:'#cfc4b6'},b); E('circle',{cx:-6,cy:-14,r:2,fill:'#cfc4b6'},b);
  const tail=E('path',{d:'M6,-36 C14,-33 17,-26 13,-20 L8,-26 Z',fill:col,stroke:INK,'stroke-width':2.5,'stroke-linejoin':'round'},b);
  rrect(-15,-43,30,10,5,{fill:col,stroke:INK,'stroke-width':3},b);
  E('circle',Object.assign({cx:0,cy:-55,r:17,fill:'#ffd9b8'},sw),b);
  const face=E('g',{},b);
  E('ellipse',{cx:-6,cy:-56,rx:2.6,ry:3.4,fill:INK},face); E('ellipse',{cx:6,cy:-56,rx:2.6,ry:3.4,fill:INK},face);
  E('circle',{cx:-11,cy:-50,r:3.2,fill:'#ff9a8a',opacity:.85},face); E('circle',{cx:11,cy:-50,r:3.2,fill:'#ff9a8a',opacity:.85},face);
  const mouth=E('path',{d:'M-3.5,-49 Q0,-45.5 3.5,-49',fill:'none',stroke:INK,'stroke-width':2,'stroke-linecap':'round'},face);
  const hair=E('circle',{cx:0,cy:-56,r:14,fill:'#9a6644'},b);
  E('path',Object.assign({d:'M-13,-70 C-25,-72 -24,-90 -12,-89 C-11,-101 11,-101 12,-89 C24,-90 25,-72 13,-70 Z',fill:'#fffdf8','stroke-linejoin':'round'},sw),b);
  rrect(-13,-75,26,8,3,{fill:'#fffdf8',stroke:INK,'stroke-width':3},b);
  const front=E('g',{},b);
  const kn=E('g',{},b); U('i-knife',30,null,kn); show(kn,false);
  const hL=E('circle',{r:5.5,fill:'#ffd9b8',stroke:INK,'stroke-width':3},b), hR=E('circle',{r:5.5,fill:'#ffd9b8',stroke:INK,'stroke-width':3},b);
  const mk=E('g',{},g);
  E('path',{d:'M-7,4 L7,4 L0,13 Z',fill:col,stroke:INK,'stroke-width':3,'stroke-linejoin':'round'},mk);
  rrect(-17,-13,34,20,10,{fill:col,stroke:INK,'stroke-width':3},mk);
  const mt=T(i?'2P':'1P',{x:0,y:2.5,class:'m','font-size':13,fill:'#fff'},mk);
  return {i,col,g,b,ring,footL,footR,back,front,face,hair,hL,hR,kn,mk,mt,tail,mouth,
    x:0,y:0,vx:0,vy:0,fx:0,fy:1,held:null,dashT:0,dashCd:0,walk:0,sq:0,chopT:0,chopping:false,chopHint:false,ai:null,bumpT:0,title:0};
}
function resetChefs(){
  for(const c of G.chefs){ if(c.g.parentNode) c.g.parentNode.removeChild(c.g); }
  G.chefs=[buildChef(0),buildChef(1)];
  G.chefs.forEach((ch,i)=>{ const s=G.spawns[i]||[2+i*8,2]; ch.x=OX+s[0]*TS+32; ch.y=OY+s[1]*TS+36; ch.fx=0; ch.fy=1; });
  G.active=0;
}
function setHeld(ch,it){
  ch.held=it;
  if(it){ it.where=ch; ensureView(it); (ch.fy<-0.6?ch.back:ch.front).appendChild(it.view); G.items.add(it);
    if((it.t==='pot'||it.t==='pan')&&G.containers.indexOf(it)<0) G.containers.push(it); }
}
function takeHeld(ch){ const it=ch.held; ch.held=null; return it; }
function chefAnim(ch,dt){
  const sp=Math.hypot(ch.vx,ch.vy), moving=sp>35;
  if(moving) ch.walk+=dt*sp*0.06;
  const s=Math.sin(ch.walk);
  let bob=moving?-Math.abs(s)*4:0, sx=1, sy=1;
  if(!moving){ const br=Math.sin(G.t*3.2+ch.i*1.7)*0.022; sy+=br; sx-=br; }
  if(ch.title){ const p=Math.abs(Math.sin(G.t*4.2+ch.i*1.3)); bob=-p*14; const q=(1-p); if(q>0.8){ sx+=0.12*(q-0.8)*5; sy-=0.12*(q-0.8)*5; } else { sy+=0.06*p; sx-=0.04*p; } }
  if(ch.sq>0){ ch.sq=Math.max(0,ch.sq-dt*4); const q=Math.sin(ch.sq*Math.PI)*0.16; sx+=q; sy-=q; }
  if(ch.dashT>0){ sx+=0.14; sy-=0.12; }
  ch.footL.setAttribute('cy',(-3+(moving?Math.min(0,s)*4:0)).toFixed(1));
  ch.footR.setAttribute('cy',(-3+(moving?Math.min(0,-s)*4:0)).toFixed(1));
  mv2(ch.b,0,bob,sx,sy);
  mv(ch.g,ch.x,ch.y);
  const up=ch.fy<-0.6;
  show(ch.face,!up); show(ch.hair,up);
  mv(ch.face,ch.fx*5,Math.max(0,ch.fy)*2);
  ch.tail.setAttribute('transform','rotate('+(clamp(-ch.vx*0.05,-25,25)+Math.sin(G.t*9)*(moving?8:2)).toFixed(1)+' 8 -36)');
  const h=ch.held;
  if(h){
    const slot=up?ch.back:ch.front;
    if(h.view.parentNode!==slot) slot.appendChild(h.view);
    mv(h.view,ch.fx*12,up?-44:-30+ch.fy*3,0.9);
    mv(ch.hL,ch.fx*12-14,-24+ch.fy*3); mv(ch.hR,ch.fx*12+14,-24+ch.fy*3);
  } else if(ch.chopping){
    const a=Math.sin(G.t*30);
    mv(ch.hL,-18,-20); mv(ch.hR,ch.fx*16+6,-30+a*5);
  } else {
    const w=moving?s*3:0;
    mv(ch.hL,-20,-18+w); mv(ch.hR,20,-18-w);
  }
  show(ch.kn,ch.chopping);
  if(ch.chopping) mv(ch.kn,ch.fx*18+8,-34+Math.sin(G.t*30)*6,1,-20+Math.sin(G.t*30)*25);
  ch.mouth.setAttribute('d',ch.chopping||ch.dashT>0?'M-3,-49 Q0,-44 3,-49 Z':'M-3.5,-49 Q0,-45.5 3.5,-49');
  const one=G.mode===1, act=G.state==='title'?false:(one?ch.i===G.active:true);
  show(ch.mk,act); show(ch.ring,act);
  if(act) mv(ch.mk,0,-120+Math.sin(G.t*5)*3);
}
function solidAt(c,r){ const t=tileAt(c,r); return !t||t.solid; }
function pushOutRect(ch,rx,ry,rw,rh){
  const nx=clamp(ch.x,rx,rx+rw), ny=clamp(ch.y,ry,ry+rh);
  let dx=ch.x-nx, dy=ch.y-ny; const d2=dx*dx+dy*dy;
  if(d2>=CR*CR) return false;
  if(d2>1e-6){ const d=Math.sqrt(d2); ch.x+=dx/d*(CR-d); ch.y+=dy/d*(CR-d); }
  else { const l=ch.x-rx, r=rx+rw-ch.x, u=ch.y-ry, b=ry+rh-ch.y, m=Math.min(l,r,u,b);
    if(m===l) ch.x=rx-CR; else if(m===r) ch.x=rx+rw+CR; else if(m===u) ch.y=ry-CR; else ch.y=ry+rh+CR; }
  return true;
}
function collideTiles(ch){
  for(let it=0;it<2;it++){
    const c0=Math.floor((ch.x-OX-CR)/TS), c1=Math.floor((ch.x-OX+CR)/TS), r0=Math.floor((ch.y-OY-CR)/TS), r1=Math.floor((ch.y-OY+CR)/TS);
    for(let r=r0;r<=r1;r++) for(let c=c0;c<=c1;c++) if(solidAt(c,r)) pushOutRect(ch,OX+c*TS,OY+r*TS,TS,TS);
  }
}
function collideChefs(){
  const a=G.chefs[0], b=G.chefs[1];
  let dx=b.x-a.x, dy=b.y-a.y, d=Math.hypot(dx,dy);
  if(d<CR*2){ if(d<0.01){ dx=1; dy=0; d=1; } const o=(CR*2-d)/2; a.x-=dx/d*o; a.y-=dy/d*o; b.x+=dx/d*o; b.y+=dy/d*o; collideTiles(a); collideTiles(b); }
}
function chefMove(ch,ix,iy,dash,dt){
  const len=Math.hypot(ix,iy);
  if(len>0.01){ ix/=len; iy/=len; ch.fx=ix; ch.fy=iy; }
  const a=Math.min(1,dt*16);
  ch.vx=lerp(ch.vx,ix*245,a); ch.vy=lerp(ch.vy,iy*245,a);
  if(dash&&ch.dashCd<=0){ ch.dashT=0.16; ch.dashCd=0.55; sfx('dash'); for(let i=0;i<5;i++) fx('dust',ch.x-ch.fx*10+rnd(-8,8),ch.y+rnd(-4,4)); }
  ch.dashCd-=dt;
  let vx=ch.vx, vy=ch.vy;
  if(ch.dashT>0){ ch.dashT-=dt; vx=ch.fx*700; vy=ch.fy*700; if(Math.random()<0.5) fx('dust',ch.x+rnd(-6,6),ch.y+rnd(-3,3)); }
  for(let s=0;s<2;s++){ ch.x+=vx*dt/2; ch.y+=vy*dt/2; collideTiles(ch); }
  collideCart(ch);
}
function collideCart(ch){
  const k=G.cart; if(!k) return false;
  if(pushOutRect(ch,k.x-k.hw,k.y-k.hh,k.hw*2,k.hh*2)){ collideTiles(ch); if(ch.bumpT<=0){ ch.bumpT=0.6; sfx('bump'); ch.sq=0.8; } return true; }
  return false;
}
function cartUpdate(dt){
  const k=G.cart; if(!k) return;
  for(const ch of G.chefs) ch.bumpT-=dt;
  if(k.wait>0){ k.wait-=dt; }
  else {
    const ox=k.x; k.x+=k.dir*k.spd*dt;
    if(k.x>=k.maxX){ k.x=k.maxX; k.dir=-1; k.wait=0.8; } else if(k.x<=k.minX){ k.x=k.minX; k.dir=1; k.wait=0.8; }
    for(const ch of G.chefs){
      if(collideCart(ch)){
        const nx=clamp(ch.x,k.x-k.hw,k.x+k.hw), ny=clamp(ch.y,k.y-k.hh,k.y+k.hh);
        if(Math.hypot(ch.x-nx,ch.y-ny)<CR-1){ k.x=ox; k.dir*=-1; k.wait=0.35; break; }
      }
    }
  }
  const w=Math.sin(G.t*18)*(k.wait>0?0:1.2);
  mv(k.g,k.x,k.y); mv(k.b,0,w,1);
}
function targetTile(ch){
  const px=ch.x+ch.fx*42, py=ch.y+ch.fy*42;
  let t=tileAtPx(px,py); if(t&&t.solid) return t;
  const cc=Math.floor((ch.x-OX)/TS), cr=Math.floor((ch.y-OY)/TS);
  if(Math.abs(ch.fx)>=Math.abs(ch.fy)) t=tileAt(cc+Math.sign(ch.fx),cr); else t=tileAt(cc,cr+Math.sign(ch.fy));
  return t&&t.solid?t:null;
}

// ===== interaction =====
function fail(ch,msg){ sfx('bonk'); ch.sq=0.6; if(msg) popText(ch.x,ch.y-128,msg,'#fff',INK,16); return false; }
function interact(ch){
  const t=targetTile(ch); if(!t) return fail(ch);
  const k=t.k, h=ch.held;
  ch.sq=0.7;
  if(CRATE[k]){
    const kind=CRATE[k];
    if(!h){ setHeld(ch,mkItem(kind)); sfx('pick'); return true; }
    if(h.t==='plate'&&kind==='bun'&&plateAccepts(h.parts,'bun')){ h.parts.push('bun'); h.dirty=true; ensureView(h); sfx('place'); return true; }
    return fail(ch,'手里有东西');
  }
  if(k==='P'){
    if(!h){ setHeld(ch,mkItem('plate')); sfx('plate'); return true; }
    if(h.t==='plate'&&!h.parts.length){ destroyItem(takeHeld(ch)); sfx('plate'); return true; }
    return fail(ch);
  }
  if(k==='X'){ if(!h) return fail(ch); return trash(ch,t); }
  if(k==='W'){ if(!h) return fail(ch); return serve(ch,t); }
  const it=t.item;
  if(!h){ if(!it) return fail(ch); setHeld(ch,takeItem(t)); sfx('pick'); return true; }
  if(!it){
    if((k==='S'||k==='F')&&h.t!=='pot'&&h.t!=='pan') return fail(ch,'灶台只放锅');
    placeItem(t,takeHeld(ch)); sfx(h.t==='plate'?'plate':'place'); return true;
  }
  return combine(ch,h,t,it);
}
function addToPlate(pl,p){ if(!plateAccepts(pl.parts,p)) return false; pl.parts.push(p); pl.dirty=true; ensureView(pl); return true; }
function combine(ch,h,t,it){
  if(h.t==='plate'){
    const p=partOf(it);
    if(p&&addToPlate(h,p)){ destroyItem(takeItem(t)); sfx('place'); return true; }
    if(it.t==='pot'&&potReady(it)&&!h.parts.length&&addToPlate(h,'soup')){ emptyC(it); sfx('splash'); return true; }
    if(it.t==='pan'&&panReady(it)&&addToPlate(h,'patty')){ emptyC(it); sfx('place'); return true; }
    return fail(ch,it.t==='pot'&&!potReady(it)?'汤还没好':it.t==='pan'&&!panReady(it)?'肉饼还没好':(p||it.t==='meat'||it.t==='tom'||it.t==='let')&&!p?'要先处理':'放不上去');
  }
  if(it.t==='plate'){
    const p=partOf(h);
    if(p&&addToPlate(it,p)){ destroyItem(takeHeld(ch)); sfx('place'); bounce(it,t); return true; }
    if(h.t==='pot'&&potReady(h)&&!it.parts.length&&addToPlate(it,'soup')){ emptyC(h); sfx('splash'); bounce(it,t); return true; }
    if(h.t==='pan'&&panReady(h)&&addToPlate(it,'patty')){ emptyC(h); sfx('place'); bounce(it,t); return true; }
    return fail(ch,partOf(h)?'放不上去':'要先处理');
  }
  if(it.t==='pot'&&h.t==='tom'){ if(!h.ch) return fail(ch,'番茄要先切'); if(potCanAdd(it)){ it.n++; it.dirty=true; ensureView(it); destroyItem(takeHeld(ch)); sfx('splash'); bounce(it,t); return true; } return fail(ch,'锅满了'); }
  if(h.t==='pot'&&it.t==='tom'&&it.ch&&potCanAdd(h)){ h.n++; h.dirty=true; ensureView(h); destroyItem(takeItem(t)); sfx('splash'); return true; }
  if(it.t==='pan'&&h.t==='meat'){ if(!h.ch) return fail(ch,'肉要先切'); if(!it.meat&&!it.burnt){ it.meat=true; it.cook=0; it.over=0; it.dirty=true; ensureView(it); destroyItem(takeHeld(ch)); sfx('sizzle'); bounce(it,t); return true; } return fail(ch,'锅里有东西'); }
  if(h.t==='pan'&&it.t==='meat'&&it.ch&&!h.meat&&!h.burnt){ h.meat=true; h.cook=0; h.over=0; h.dirty=true; ensureView(h); destroyItem(takeItem(t)); sfx('sizzle'); return true; }
  if((it.t==='pot'||it.t==='pan')&&(h.t==='let'||h.t==='bun'||h.t==='meat'||h.t==='tom')) return fail(ch,'放不进去');
  return fail(ch,'这里有东西了');
}
const potCanAdd=p=>p.n<3&&!p.burnt;
function emptyC(c){ c.n=0; c.meat=false; c.cook=0; c.over=0; c.burnt=false; c.warnT=0; c.dirty=true; ensureView(c); }
function trash(ch,t){
  const h=ch.held;
  if(h.t==='plate'){ if(!h.parts.length) return fail(ch,'空盘子'); h.parts=[]; h.dirty=true; ensureView(h); }
  else if(h.t==='pot'||h.t==='pan'){ if(!h.n&&!h.meat) return fail(ch,'锅是空的'); emptyC(h); }
  else destroyItem(takeHeld(ch));
  sfx('trash'); for(let i=0;i<6;i++) fx('dust',t.cx+rnd(-12,12),t.cy+rnd(-10,6));
  return true;
}
function chopUpdate(ch,holdKey,dt){
  ch.chopping=false;
  if(!holdKey){ ch.chopHint=false; return; }
  const t=targetTile(ch); if(!t||t.k!=='C'||!t.item) return;
  const it=t.item; if(it.ch||(it.t!=='tom'&&it.t!=='let'&&it.t!=='meat')) return;
  if(ch.held){ if(!ch.chopHint){ ch.chopHint=true; fail(ch,'先空出双手'); } return; }
  ch.chopping=true; it.prog+=dt/G.lvl.chop; ch.chopT+=dt;
  if(ch.chopT>0.18){ ch.chopT=0; sfx('chop'); ch.sq=0.35; chopBits(t,it); }
  if(it.prog>=1){ it.prog=0; it.ch=true; it.dirty=true; ensureView(it); sfx('done'); bounce(it,t); for(let i=0;i<6;i++) fx('spark',t.cx+rnd(-14,14),t.cy-10+rnd(-10,6)); }
}
function bounce(it,t){ G.bouncing.push({it,t:0,x:t.cx,y:t.cy}); }

// ===== cooking =====
function cookUpdate(dt){
  for(const it of G.containers){
    const w=it.where, onStove=w&&w.k&&(w.k==='S'||w.k==='F')&&w.item===it;
    const busy=(it.t==='pot'&&it.n>=3)||(it.t==='pan'&&it.meat);
    if(onStove&&busy&&!it.burnt){
      const ct=it.t==='pot'?G.lvl.cook:G.lvl.patty, bt=it.t==='pot'?G.lvl.burn:G.lvl.pburn;
      if(it.cook<1){ it.cook+=dt/ct; if(it.cook>=1){ it.cook=1; it.dirty=true; ensureView(it); sfx('done'); popText(w.cx,w.cy-50,'好了!',MINT,INK,18); } }
      else {
        it.over+=dt;
        if(it.over>bt*0.4){ it.warnT-=dt; if(it.warnT<=0){ it.warnT=0.45; sfx('warn'); } }
        if(it.over>=bt){ it.burnt=true; it.dirty=true; ensureView(it); G.stats.burnt++; sfx('burnt'); G.shake=Math.max(G.shake,0.35); popText(w.cx,w.cy-54,'烧焦了!',RED,'#fff',20); for(let i=0;i<10;i++) fx('smoke',w.cx+rnd(-12,12),w.cy-10); }
      }
      if(Math.random()<dt*(it.t==='pot'?5:9)){ const p=itemPos(it); fx(it.t==='pot'?'steam':'sizzle',p[0]+rnd(-12,12),p[1]-12); }
      if(it.t==='pan'&&Math.random()<dt*2.2) sfx('sizzle');
      if(it.t==='pot'&&Math.random()<dt*2) sfx('bubble');
    } else if(!it.burnt&&it.t==='pot'&&it.cook>=1&&Math.random()<dt*2.5){ const p=itemPos(it); fx('steam',p[0]+rnd(-10,10),p[1]-12); }
    if(it.burnt&&Math.random()<dt*7){ const p=itemPos(it); fx('smoke',p[0]+rnd(-10,10),p[1]-24); }
    const r=it.refs; if(!r) continue;
    const cooking=busy&&!it.burnt&&it.cook<1, done=busy&&!it.burnt&&it.cook>=1;
    const bt=it.t==='pot'?G.lvl.burn:G.lvl.pburn, warn=done&&it.over>bt*0.4;
    show(r.rg,cooking&&it.cook>0); if(cooking) r.arc.setAttribute('stroke-dashoffset',(41*(1-it.cook)).toFixed(1));
    show(r.ok,done&&!warn);
    show(r.warn,warn&&(G.t*6%2<1.2));
    if(warn) mv(r.warn,Math.sin(G.t*40)*2,-46);
    show(r.fire,it.burnt);
    if(it.burnt) mv2(r.fire,0,-18,1+Math.sin(G.t*20)*0.08,1+Math.cos(G.t*17)*0.14);
  }
  for(const t of G.tiles){
    if(t.fx.glow){ const it=t.item, on=it&&!it.burnt&&((it.t==='pot'&&it.n>=3)||(it.t==='pan'&&it.meat)); show(t.fx.glow,!!on); if(on) t.fx.glow.setAttribute('opacity',(0.75+Math.sin(G.t*13+t.c)*0.25).toFixed(2)); }
    if(t.fx.bar){ const it=t.item, on=it&&!it.ch&&it.prog>0; show(t.fx.bar,!!on); if(on) t.fx.fill.setAttribute('width',(46*Math.min(1,it.prog)).toFixed(1)); show(t.fx.knife,!G.chefs.some(c=>c.chopping&&targetTile(c)===t)); }
  }
}

