function keycap(p,x,y,label,w){
  const g=Gp(x,y,p); w=w||Math.max(28,label.length*9+14);
  rrect(-w/2,-13,w,28,7,{fill:'#bfa983'},g);
  rrect(-w/2,-15,w,26,7,{fill:'#fff',stroke:INK,'stroke-width':2.5},g);
  T(label,{x:0,y:3,class:'m','font-size':label.length>3?11:13},g);
  return g;
}
function panel(p,x,y,w,h,title,col){
  rrect(x+4,y+6,w,h,16,{fill:INK,opacity:.28},p);
  rrect(x,y,w,h,16,{fill:PAPER,stroke:INK,'stroke-width':3.5},p);
  const hb=E('path',{d:`M${x+1.7},${y+34} L${x+1.7},${y+16} Q${x+1.7},${y+1.7} ${x+16},${y+1.7} L${x+w-16},${y+1.7} Q${x+w-1.7},${y+1.7} ${x+w-1.7},${y+16} L${x+w-1.7},${y+34} Z`,fill:col||YEL},p);
  E('path',{d:`M${x+2},${y+34} L${x+w-2},${y+34}`,stroke:INK,'stroke-width':2.5},p);
  T(title,{x:x+w/2,y:y+24,class:'m','font-size':16,fill:col&&col!==YEL?'#fff':INK},p);
  return hb;
}
function legendRows(p,x,y,rows){
  rows.forEach((r,i)=>{
    const yy=y+i*60, keys=r[0], n=keys.length;
    const ws=keys.map(k=>k==='/'?10:Math.max(28,k.length*9+14)), tw=ws.reduce((a,b)=>a+b,0)+(n-1)*4;
    let cx=x-tw/2;
    keys.forEach((k,j)=>{ if(k==='/') T('/',{x:cx+5,y:yy+5,class:'m','font-size':14}); else keycap(p,cx+ws[j]/2,yy,k,ws[j]); cx+=ws[j]+4; });
    T(r[1],{x,y:yy+32,class:'m','font-size':13,fill:'#6b5446'},p);
  });
}
function buildLegends(){
