function recipeBook(p,x,y,w,h){
  panel(p,x,y,w,h,'菜谱 RECIPES',MINT);
  const rs=G.lvl.recipes, gap=Math.min(74,(h-44)/rs.length);
  rs.forEach((k,i)=>{
    const R=RECIPES[k], yy=y+44+i*gap;
    T(R.name,{x:x+12,y:yy+13,'font-size':13},p);
    U(R.icon,34,null,Gp(x+28,yy+38,p));
    T('=',{x:x+52,y:yy+44,class:'m','font-size':15},p);
    const ing=R.ing.filter(s=>s!=='i-pot'&&s!=='i-pan');
    const shown=k==='soup'?['i-tomC','i-pot']:ing;
    if(k==='soup') T('3×',{x:x+70,y:yy+44,class:'m','font-size':12},p);
    shown.forEach((s,j)=>U(s,24,null,Gp(x+(k==='soup'?92:74)+j*25,yy+38,p)));
  });
}

// ===== orders =====
function ticketX(i){ return 20+i*160; }
function spawnOrder(){
  const lv=G.lvl, live=G.orders.filter(o=>o.state==='live');
  if(live.length>=lv.maxOrders) return;
  const slot=UI.tk.find(s=>!s.o); if(!slot) return;
  let r=lv.recipes[0];
  for(let k=0;k<6;k++){ r=lv.recipes[Math.floor(Math.random()*lv.recipes.length)]; if(!(G.lastR===r&&G.lastR2===r)) break; }
  G.lastR2=G.lastR; G.lastR=r;
  const R=RECIPES[r], tot=R.time*lv.timeMul;
  const o={r,total:tot,left:tot,state:'live',slot,gt:0,t:0,id:++G.orderSeq};
  slot.o=o; slot.name.textContent=R.name; slot.band.setAttribute('fill',R.band);
  slot.dish.setAttribute('href','#'+R.icon);
  slot.ing.forEach((u,j)=>{ const s=R.ing[j]; show(u,!!s); if(s) u.setAttribute('href','#'+s); });
  show(slot.ok,false); show(slot.no,false); show(slot.g,true);
  slot.x=ticketX(live.length); slot.y=-150; slot.rot=rnd(-2.5,2.5);
  HUD.insertBefore(slot.g,UI.ck);
  G.orders.push(o); sfx('order');
}
function ordersUpdate(dt){
  G.nextOrder-=dt;
  let live=G.orders.filter(o=>o.state==='live');
  if((G.nextOrder<=0||live.length===0)&&live.length<G.lvl.maxOrders&&G.time>10){ spawnOrder(); G.nextOrder=G.lvl.interval*rnd(0.85,1.15); }
  for(const o of G.orders){
    o.t+=dt;
    if(o.state==='live'){ o.left-=dt; if(o.left<=0) expire(o); }
    else o.gt+=dt;
  }
  for(let i=G.orders.length-1;i>=0;i--){ const o=G.orders[i]; if(o.state!=='live'&&o.gt>0.9){ o.slot.o=null; show(o.slot.g,false); G.orders.splice(i,1); } }
}
function expire(o){
  o.state='fail'; o.gt=0; G.score=Math.max(0,G.score-G.lvl.penalty); G.stats.expired++;
  sfx('expire'); G.shake=Math.max(G.shake,0.25); show(o.slot.no,true);
  popText(o.slot.x+75,150,'-'+G.lvl.penalty+' 超时!',RED,'#fff',22);
}
function ticketsRender(dt){
  let idx=0;
  for(const o of G.orders){
    const s=o.slot;
    if(o.state==='live'){
      s.x=lerp(s.x,ticketX(idx),Math.min(1,dt*10)); idx++;
      const y=-150+158*easeOutBack(o.t/0.55), f=o.left/o.total;
      const urgent=f<0.25, sh=urgent?Math.sin(G.t*38)*2.2:0;
      mv(s.g,s.x+sh,y,1,s.rot+(urgent?Math.sin(G.t*30)*1.6:0));
      s.bar.setAttribute('width',Math.max(0,126*f).toFixed(1));
      s.bar.setAttribute('fill',f>0.5?MINT:f>0.25?YEL:RED);
    } else if(o.state==='done'){
      const p=o.gt/0.9; mv(s.g,s.x,8-p*p*180,1+p*0.15,s.rot);
      s.g.setAttribute('opacity',(1-Math.max(0,p-0.5)*2).toFixed(2));
    } else {
      const p=o.gt/0.9; mv(s.g,s.x,8+p*p*260,1,s.rot+p*40);
      s.g.setAttribute('opacity',(1-p).toFixed(2));
    }
    if(o.state==='live') s.g.setAttribute('opacity','1');
  }
}
function serve(ch,t){
  const h=ch.held;
  if(h.t!=='plate') return fail(ch,h.t==='pot'||h.t==='pan'?'要先装盘':'要装盘才能上菜');
  if(!h.parts.length) return fail(ch,'空盘子');
  const r=recipeOf(h.parts), o=r&&G.orders.find(x=>x.state==='live'&&x.r===r);
  if(!o){
    G.stats.wrong++; sfx('buzz'); ch.sq=1; G.shake=Math.max(G.shake,0.15);
    popText(t.cx-50,t.cy-64,r?'没人点这道菜':'菜还没做完',RED,'#fff',18); return false;
  }
  const frac=o.left/o.total, tip=Math.round(G.lvl.tip*frac), gain=RECIPES[r].reward+tip;
  G.score+=gain; G.stats.served++; G.stats.tips+=tip;
  destroyItem(takeHeld(ch)); o.state='done'; o.gt=0; show(o.slot.ok,true);
  sfx('ding'); popText(t.cx-128,t.cy-22,'+'+gain,YEL,INK,32);
  if(tip>0) popText(t.cx-128,t.cy+8,'小费 +'+tip,'#fff',INK,15);
  coinBurst(t.cx,t.cy-20,Math.min(10,3+Math.round(gain/6)));
  for(let i=0;i<10;i++) fx('spark',t.cx+rnd(-20,20),t.cy-10+rnd(-20,10));
  return true;
}
function hudUpdate(dt){
  const f=G.time/ROUND;
  UI.ckRing.setAttribute('stroke-dashoffset',(CKC*(1-f)).toFixed(1));
  UI.ckRing.setAttribute('stroke',G.time>60?MINT:G.time>20?YEL:RED);
  UI.ckTxt.textContent=fmtTime(G.time);
  const cs=G.time<10&&G.state==='playing'?Math.sin(G.t*40)*3:0;
  mv(UI.ck,905+cs,66,G.time<10?1+Math.max(0,Math.sin(G.t*Math.PI*2))*0.06:1);
  if(G.shown!==G.score){ const d=G.score-G.shown; G.shown+=Math.sign(d)*Math.max(1,Math.ceil(Math.abs(d)*dt*6)); if(Math.abs(G.score-G.shown)<1) G.shown=G.score; }
  UI.score.textContent=String(Math.round(G.shown));
  const th=G.lvl.stars;
  UI.starFill.setAttribute('width',(155*clamp(G.shown/th[2],0,1)).toFixed(1));
  UI.stars.forEach((s,i)=>{
    const lit=G.shown>=th[i];
    if(lit&&!s.lit){ s.pop=1; if(G.state==='playing') sfx('star'); }
    if(lit!==s.lit){ s.lit=lit; s.u.setAttribute('fill',lit?YEL:'#d8c7a8'); }
    if(s.pop>0) s.pop=Math.max(0,s.pop-dt*2.5);
    mv(s.g,s.x,107,1+Math.sin(s.pop*Math.PI)*0.7,s.pop*60);
  });
  if(UI.coinPop>0){ UI.coinPop=Math.max(0,UI.coinPop-dt*5); }
  mv(UI.coin,1004,53,1+Math.sin((UI.coinPop||0)*Math.PI)*0.2);
  if(UI.av) UI.av.forEach((a,i)=>{ show(a.hl,i===G.active); mv(a.g,1194+(i?32:-32),236+(i===G.active?Math.sin(G.t*6)*2:0),i===G.active?1.08:0.9); });
}
function hudLevel(){
  const th=G.lvl.stars;
  UI.stars.forEach((s,i)=>{ s.x=995+155*th[i]/th[2]; s.lit=false; s.pop=0; s.u.setAttribute('fill','#d8c7a8'); });
  UI.tk.forEach(s=>{ s.o=null; show(s.g,false); });
  buildLegends();
}

// ===== particles, popups, coins =====
const PART=[], POPS=[];
let partIx=0, popIx=0;
function initFx(){
  for(let i=0;i<160;i++){ const e=E('rect',{x:-4,y:-4,width:8,height:8,rx:4},L.part); show(e,false); PART.push({e,on:false}); }
  for(let i=0;i<14;i++){ const e=T('',{class:'m o','font-size':20,'stroke-width':5},L.pop); show(e,false); POPS.push({e,on:false}); }
}
const FXK={
  dust:{c:['#fff3dc','#f3dcb8'],s:[10,16],life:0.45,vy:[-30,-10],vx:[-30,30],g:0,grow:1.9,o:0.9,rx:4},
  steam:{c:['#ffffff'],s:[10,16],life:1.1,vy:[-50,-30],vx:[-8,8],g:0,grow:2.2,o:0.75,rx:4},
  smoke:{c:['#4b4242','#6a6060'],s:[14,20],life:1.3,vy:[-55,-35],vx:[-10,10],g:0,grow:2.3,o:0.65,rx:4},
  sizzle:{c:[YEL,'#ffb347','#fff'],s:[4,6],life:0.4,vy:[-110,-50],vx:[-60,60],g:260,grow:0.6,o:1,rx:2},
  spark:{c:['#fff',YEL,MINT],s:[5,8],life:0.5,vy:[-150,-40],vx:[-110,110],g:120,grow:0.4,o:1,rx:1},
  bit:{c:[RED],s:[6,9],life:0.6,vy:[-190,-80],vx:[-120,120],g:620,grow:1,o:1,rx:2}
};
function fx(kind,x,y,col){
  const k=FXK[kind]; let p=null;
  for(let n=0;n<PART.length;n++){ const q=PART[(partIx+n)%PART.length]; if(!q.on){ p=q; partIx=(partIx+n+1)%PART.length; break; } }
  if(!p) return;
  p.on=true; p.x=x; p.y=y; p.vx=rnd(k.vx[0],k.vx[1]); p.vy=rnd(k.vy[0],k.vy[1]); p.g=k.g; p.life=p.max=k.life*rnd(0.8,1.2);
  p.s0=rnd(k.s[0],k.s[1]); p.grow=k.grow; p.o=k.o; p.rot=rnd(0,360); p.vr=kind==='bit'||kind==='spark'?rnd(-600,600):0;
  const c=col||k.c[Math.floor(Math.random()*k.c.length)];
  p.e.setAttribute('fill',c); p.e.setAttribute('rx',k.rx);
  if(kind==='bit'){ p.e.setAttribute('stroke',INK); p.e.setAttribute('stroke-width',1.5); } else p.e.removeAttribute('stroke');
  show(p.e,true);
}
function chopBits(t,it){
  const c=it.t==='tom'?[RED,'#ff8f7f']:it.t==='let'?['#7cc943','#a6e36a']:['#e8676b','#ffc6c3'];
  for(let i=0;i<4;i++) fx('bit',t.cx+rnd(-10,10),t.cy-6,c[i%2]);
}
function fxUpdate(dt){
  for(const p of PART){
    if(!p.on) continue;
    p.life-=dt; if(p.life<=0){ p.on=false; show(p.e,false); continue; }
    p.vy+=p.g*dt; p.x+=p.vx*dt; p.y+=p.vy*dt; p.rot+=p.vr*dt;
    const f=1-p.life/p.max, s=p.s0*(1+(p.grow-1)*f)/8;
    p.e.setAttribute('transform','translate('+p.x.toFixed(1)+','+p.y.toFixed(1)+') rotate('+p.rot.toFixed(0)+') scale('+s.toFixed(2)+')');
    p.e.setAttribute('opacity',(p.o*Math.min(1,p.life/p.max*1.6)).toFixed(2));
  }
  for(const p of POPS){
    if(!p.on) continue;
    p.t+=dt; if(p.t>=p.max){ p.on=false; show(p.e,false); continue; }
    p.y-=34*dt;
    mv(p.e,p.x,p.y,easeOutBack(p.t/0.25));
    p.e.setAttribute('opacity',Math.min(1,(p.max-p.t)*3).toFixed(2));
  }
  for(const c of UI.coins){
    if(!c.on) continue;
    c.t+=dt; if(c.t<0){ show(c.e,false); continue; }
    show(c.e,true);
    const p=Math.min(1,c.t/0.75), e=p*p, x=(1-e)*(1-e)*c.x0+2*(1-e)*e*c.cx+e*e*1004, y=(1-e)*(1-e)*c.y0+2*(1-e)*e*c.cy+e*e*53;
    mv(c.e,x,y,1+Math.sin(p*Math.PI)*0.5);
    if(p>=1){ c.on=false; show(c.e,false); UI.coinPop=1; sfx('coin'); }
  }
  for(let i=G.bouncing.length-1;i>=0;i--){
    const b=G.bouncing[i]; b.t+=dt;
    const q=b.t<0.3?Math.sin(b.t/0.3*Math.PI)*(1-b.t/0.3):0;
    if(b.it.where&&b.it.where.item===b.it) mv2(b.it.view,b.x,b.y-q*10,1+q*0.25,1-q*0.2);
    if(b.t>=0.3){ if(b.it.where&&b.it.where.item===b.it) mv(b.it.view,b.x,b.y); G.bouncing.splice(i,1); }
  }
}
function popText(x,y,s,fill,stroke,size){
  const p=POPS[popIx]; popIx=(popIx+1)%POPS.length;
  p.on=true; p.t=0; p.max=1.1; p.x=clamp(x,70,1210); p.y=y;
  p.e.textContent=s; p.e.setAttribute('fill',fill||'#fff'); p.e.setAttribute('stroke',stroke||INK); p.e.setAttribute('font-size',size||20);
  show(p.e,true); mv(p.e,p.x,p.y,0.2);
}
function coinBurst(x,y,n){
  let k=0;
  for(const c of UI.coins){ if(k>=n) break; if(c.on) continue; c.on=true; c.t=-k*0.07; c.x0=x+rnd(-10,10); c.y0=y; c.cx=x+rnd(-120,40); c.cy=y-rnd(150,260); k++; }
}
function clearFx(){
  for(const p of PART){ p.on=false; show(p.e,false); }
  for(const p of POPS){ p.on=false; show(p.e,false); }
  for(const c of UI.coins){ c.on=false; show(c.e,false); }
}

