function titleDecor(){
  const lv=G.lvl;
  const boards=G.tiles.filter(t=>t.k==='C'), cnt=G.tiles.filter(t=>t.k==='#'&&t.r>0&&t.r<GH-1&&t.c>0&&t.c<GW-1);
  if(boards[0]) placeItem(boards[0],mkItem('tom'),true);
  if(boards[1]) placeItem(boards[1],mkItem('let',{ch:true}),true);
  for(const t of G.tiles){
    if(t.k==='S'&&t.item&&t.item.t==='pot'&&!G.tiles.some(q=>q!==t&&q.k==='S'&&q.item&&q.item.n)){ t.item.n=3; t.item.cook=1; t.item.dirty=true; ensureView(t.item); }
    if(t.k==='F'&&t.item&&!G.tiles.some(q=>q!==t&&q.k==='F'&&q.item&&q.item.meat)){ t.item.meat=true; t.item.cook=0.5; t.item.dirty=true; ensureView(t.item); }
  }
  const pl=mkItem('plate',{parts:lv.recipes.indexOf('salad')>=0?['letC','tomC']:['bun','patty','letC']});
  if(cnt[0]) placeItem(cnt[0],pl,true);
  G.chefs.forEach((ch,i)=>{ ch.title=1; ch.x=OX+(i?10:3)*TS+32; ch.y=OY+3*TS+40; ch.fx=0; ch.fy=1; });
}
function titleUpdate(dt){
  UI.logoCh.forEach((c,i)=>{ const p=Math.abs(Math.sin(G.t*2.6+i*0.55)); const s=p<0.15?1+(0.15-p)*0.8:1; mv2(c,-208+i*104,132-p*9,s,2-s); });
  UI.cards.forEach((c,i)=>{ const on=G.sel===i; show(c.glow,on); if(on) c.glow.setAttribute('opacity',(0.6+Math.sin(G.t*6)*0.4).toFixed(2)); mv(c.b,380+i*197,496+(on?-6+Math.sin(G.t*4)*1.5:0)); });
  G.chefs.forEach((ch,i)=>{ const k=Math.floor(G.t/2.2+i*0.7)%4; ch.fx=[0,0.9,0,-0.9][k]; ch.fy=[1,0.4,1,0.4][k]; });
  for(const it of G.containers){ const p=itemPos(it); if(it.t==='pot'&&it.cook>=1&&Math.random()<dt*4) fx('steam',p[0]+rnd(-10,10),p[1]-14); if(it.t==='pan'&&it.meat&&Math.random()<dt*6) fx('sizzle',p[0]+rnd(-10,10),p[1]-8); }
  for(const t of G.tiles) if(t.fx.glow){ const it=t.item, on=it&&((it.t==='pot'&&it.n>=3)||(it.t==='pan'&&it.meat)); show(t.fx.glow,!!on); }
}
