  E('path',{d:'M-11,-5 L-5,-5 L2,-11 L2,11 L-5,5 L-11,5 Z',fill:INK,'stroke-linejoin':'round',stroke:INK,'stroke-width':2},mb);
  UI.muteW=E('path',{d:'M6,-6 Q10,0 6,6 M9,-10 Q16,0 9,10',fill:'none',stroke:INK,'stroke-width':2.8,'stroke-linecap':'round'},mb);
  UI.muteX=E('path',{d:'M6,-6 L14,6 M14,-6 L6,6',stroke:RED,'stroke-width':3.5,'stroke-linecap':'round'},mb);
  show(UI.muteX,false);
  btn('*',1214,22,44,44,()=>setMute(!AU.muted));
  btn('playing',1214,80,44,44,pauseGame);
  UI.conf=[]; const cg=E('g',{class:'np'},g);
  for(let i=0;i<70;i++){ const e=E('rect',{x:-5,y:-3,width:10,height:6,rx:1.5},cg); show(e,false); UI.conf.push({e,on:false}); }
}
function confetti(n){
  const cols=[RED,YEL,MINT,SKY,'#fff','#ff9ad0'];
  let k=0;
  for(const c of UI.conf){ if(k>=n) break; if(c.on) continue; k++;
    c.on=true; c.x=rnd(300,980); c.y=rnd(-60,-10); c.vx=rnd(-60,60); c.vy=rnd(60,220); c.r=rnd(0,360); c.vr=rnd(-400,400); c.life=rnd(2.5,4);
    c.e.setAttribute('fill',cols[k%cols.length]); show(c.e,true); }
}
function confUpdate(dt){
  for(const c of UI.conf){ if(!c.on) continue; c.life-=dt; if(c.life<=0||c.y>760){ c.on=false; show(c.e,false); continue; }
    c.vy=Math.min(c.vy+160*dt,240); c.x+=(c.vx+Math.sin(c.life*5)*40)*dt; c.y+=c.vy*dt; c.r+=c.vr*dt;
    c.e.setAttribute('transform','translate('+c.x.toFixed(1)+','+c.y.toFixed(1)+') rotate('+c.r.toFixed(0)+') scale(1,'+Math.cos(c.life*7).toFixed(2)+')'); }
}

// ===== flow =====
function newStats(){ return {served:0,tips:0,expired:0,burnt:0,wrong:0}; }
function selLevel(i){
  i=(i+LEVELS.length)%LEVELS.length; if(i===G.sel&&G.lvl===LEVELS[i]) return;
  G.sel=i; sfx('click'); enterTitleKitchen();
}
function setMode(m){ if(G.mode!==m){ G.mode=m; sfx('swap'); } refreshTitle(); }
function enterTitleKitchen(){
  buildKitchen(G.sel); resetChefs(); clearFx(); titleDecor(); refreshTitle();
}
function hideAll(){ show(SCR.title,false); show(SCR.count,false); show(SCR.pause,false); show(SCR.over,false); show(SCR.help,false); }
function toTitle(){
  hideAll(); AU.music=false; G.state='title'; G.botOn=0; G.speed=1;
  show(HUD,false); show(SCR.title,true); enterTitleKitchen();
  L.world.removeAttribute('transform');
}
function startGame(li,withCount){
  auInit(); hideAll();
  G.sel=li; buildKitchen(li); resetChefs(); clearFx();
  G.score=0; G.shown=0; G.time=ROUND; G.stats=newStats(); G.orders=[]; G.nextOrder=0; G.lastTick=99; G.shake=0;
  G.lastR=G.lastR2=null; G.overT=0; G.newBest=false;
  for(const k in KEYS) KEYS[k]=false; PRESSED.clear();
  hudLevel(); show(HUD,true); hudUpdate(0);
  if(withCount){ G.state='countdown'; G.cd=2.6; show(SCR.count,true); UI.cdLvl.textContent=G.lvl.diff+' · '+G.lvl.name+' · '+(G.mode===2?'双人合作':'单人'); sfx('beep'); G.cdBeat=2; }
  else { G.state='playing'; AU.music=true; }
}
function pauseGame(){ if(G.state!=='playing') return; G.state='paused'; AU.music=false; show(SCR.pause,true); for(const k in KEYS) KEYS[k]=false; }
function resume(){ if(G.state!=='paused') return; G.state='playing'; AU.music=true; show(SCR.pause,false); last=performance.now(); }
function openHelp(){ if(G.state!=='title') return; G.state='help'; show(SCR.help,true); sfx('click'); }
function closeHelp(){ if(G.state!=='help') return; G.state='title'; show(SCR.help,false); sfx('click'); }
function endRound(){
  G.state='over'; G.overT=0; AU.music=false;
  for(const ch of G.chefs){ ch.chopping=false; ch.ai=null; }
  const th=G.lvl.stars, stars=th.filter(s=>G.score>=s).length; G.starsEarned=stars;
  const kb=loadBest(G.li); G.newBest=G.score>kb&&G.score>0;
  if(G.newBest) saveBest(G.li,G.score);
  if(G.score>loadBest(null)) saveBest(null,G.score);
  UI.ovTitle.textContent=stars===3?'大厨驾到！':stars>=1?'打烊啦！':'下次加油！';
  UI.ovSub.textContent="TIME'S UP · "+G.lvl.diff+' · '+G.lvl.name+' · '+(G.mode===2?'双人合作':'单人');
  UI.ovStars.forEach((s,i)=>{ s.on=false; show(s.gold,false); s.th.textContent=th[i]+' 分'; });
  UI.ovScore.textContent=String(G.score);
  show(UI.ovNew,false);
  const st=G.stats, vals=[st.served+' 份','+'+st.tips,st.expired+' 单',st.burnt+' 次',st.wrong+' 次',String(Math.max(kb,G.score))];
  vals.forEach((v,i)=>{ UI.ovStats[i].textContent=v; });
  show(SCR.over,true); sfx('fanfare');
}
function overUpdate(dt){
  G.overT+=dt;
  UI.ovStars.forEach((s,i)=>{
    const t0=0.6+i*0.45;
    if(!s.on&&i<G.starsEarned&&G.overT>=t0){ s.on=true; show(s.gold,true); sfx('star'); }
    if(s.on){ const p=clamp((G.overT-t0)/0.45,0,1); mv(s.gold,0,0,easeOutBack(p),(1-p)*-90); }
  });
  if(G.newBest&&G.overT>2.0){ show(UI.ovNew,true); mv(UI.ovNew,846,322,1+Math.sin(G.t*6)*0.05,-8); }
  if(G.starsEarned===3&&!G.confDone&&G.overT>2.0){ G.confDone=true; confetti(70); sfx('fanfare'); }
  if(G.overT<0.1) G.confDone=false;
}

// ===== input =====
const KEYS={}, PRESSED=new Set();
const MAP1={up:['KeyW','ArrowUp'],down:['KeyS','ArrowDown'],left:['KeyA','ArrowLeft'],right:['KeyD','ArrowRight'],pick:['Space','KeyJ','KeyE','KeyF'],chop:['KeyK','KeyG'],dash:['ShiftLeft','ShiftRight'],swap:['Tab']};
const MAP2=[{up:['KeyW'],down:['KeyS'],left:['KeyA'],right:['KeyD'],pick:['KeyF'],chop:['KeyG'],dash:['ShiftLeft']},
  {up:['ArrowUp'],down:['ArrowDown'],left:['ArrowLeft'],right:['ArrowRight'],pick:['Period','Numpad1'],chop:['Slash','Numpad2'],dash:['ShiftRight','Numpad0']}];
const USED=new Set(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','Tab','Enter','NumpadEnter','Escape','Slash','Period','Quote','KeyW','KeyA','KeyS','KeyD','KeyJ','KeyK','KeyE','KeyF','KeyG','KeyP','KeyH','KeyM','KeyR','KeyQ','Numpad0','Numpad1','Numpad2','Digit1','Digit2','ShiftLeft','ShiftRight']);
const isHeld=a=>a.some(k=>KEYS[k])?1:0, isPressed=a=>a.some(k=>PRESSED.has(k));
window.addEventListener('keydown',e=>{
  const c=e.code;
  if(USED.has(c)) e.preventDefault();
  if(e.repeat) return;
  auInit();
  if(c==='KeyM'){ setMute(!AU.muted); return; }
  const s=G.state;
  if(s==='title'){
    if(c==='ArrowLeft'||c==='KeyA') selLevel(G.sel-1);
    else if(c==='ArrowRight'||c==='KeyD') selLevel(G.sel+1);
    else if(c==='ArrowUp'||c==='ArrowDown'||c==='KeyW'||c==='KeyS'||c==='Tab') setMode(G.mode===1?2:1);
    else if(c==='Digit1') setMode(1); else if(c==='Digit2') setMode(2);
    else if(c==='Enter'||c==='NumpadEnter'||c==='Space') startGame(G.sel,true);
    else if(c==='KeyH') openHelp();
  } else if(s==='help'){
    if(c==='Escape'||c==='Enter'||c==='KeyH'||c==='Space'||c==='NumpadEnter') closeHelp();
  } else if(s==='playing'||s==='countdown'){
    if((c==='KeyP'||c==='Escape')&&s==='playing') pauseGame();
    else { KEYS[c]=true; if(s==='playing') PRESSED.add(c); }
  } else if(s==='paused'){
    if(c==='KeyP'||c==='Enter'||c==='Space'||c==='NumpadEnter') resume();
    else if(c==='KeyR') startGame(G.li,true);
    else if(c==='Escape'||c==='KeyQ') toTitle();
  } else if(s==='over'){
    if((c==='Enter'||c==='Space'||c==='KeyR'||c==='NumpadEnter')&&G.overT>0.5) startGame(G.li,true);
    else if(c==='Escape'&&G.overT>0.3) toTitle();
  }
});
window.addEventListener('keyup',e=>{ KEYS[e.code]=false; if(USED.has(e.code)) e.preventDefault(); });
function toView(e){
  const m=root.getScreenCTM(); if(!m) return {x:e.clientX,y:e.clientY};
  const p=root.createSVGPoint(); p.x=e.clientX; p.y=e.clientY; const q=p.matrixTransform(m.inverse());
  return {x:q.x,y:q.y};
}
function hitBtn(pt){
  for(let i=BTNS.length-1;i>=0;i--){ const b=BTNS[i]; if(b.scr!==G.state&&b.scr!=='*') continue;
    if(pt.x>=b.x&&pt.x<=b.x+b.w&&pt.y>=b.y&&pt.y<=b.y+b.h) return b; }
  return null;
}
root.addEventListener('pointerdown',e=>{
  try{ window.focus(); }catch(_){}
  auInit();
  const b=hitBtn(toView(e));
  if(b){ e.preventDefault(); sfx('click'); b.act(); }
});
root.addEventListener('pointermove',e=>{ root.style.cursor=hitBtn(toView(e))?'pointer':'default'; });
window.addEventListener('blur',()=>{ if(G.state==='playing') pauseGame(); for(const k in KEYS) KEYS[k]=false; });
document.addEventListener('visibilitychange',()=>{ if(document.hidden&&G.state==='playing') pauseGame(); });

// ===== bot (debug autoplay) =====
const DIRS=[[1,0],[-1,0],[0,1],[0,-1]];
const RES=new Map();
const cellOf=ch=>[Math.floor((ch.x-OX)/TS),Math.floor((ch.y-OY)/TS)];
function reachable(t){ return DIRS.some(d=>{ const n=tileAt(t.c+d[0],t.r+d[1]); return n&&!n.solid; }); }
function resOther(ch,t){ const v=RES.get(t); return v!=null&&v!==ch.i; }
function reserve(ch,t){ if(t) RES.set(t,ch.i); return t; }
function releaseRes(ch){ for(const [t,v] of RES) if(v===ch.i) RES.delete(t); }
function nearestT(ch,pred){
  let best=null, bd=1e9;
  for(const t of G.tiles){ if(!t.solid||!pred(t)||resOther(ch,t)||!reachable(t)) continue;
    const d=Math.abs(t.cx-ch.x)+Math.abs(t.cy-ch.y); if(d<bd){ bd=d; best=t; } }
  return best;
}
function blockedCells(ch){
  const s=new Set();
  for(const o of G.chefs) if(o!==ch){ const c=cellOf(o); s.add(c[1]*GW+c[0]); }
  if(G.cart){ const k=G.cart, c=Math.floor((k.x-OX)/TS), r=Math.floor((k.y-OY)/TS); s.add(r*GW+c); s.add(r*GW+c+k.dir); s.add(r*GW+c-k.dir); }
  return s;
}
function bfsPath(ch,tile,ignoreBlock){
  const [sc,sr]=cellOf(ch), start=sr*GW+sc, block=ignoreBlock?new Set():blockedCells(ch);
  const goals=new Set();
  DIRS.forEach(d=>{ const n=tileAt(tile.c+d[0],tile.r+d[1]); if(n&&!n.solid&&!block.has(n.r*GW+n.c)) goals.add(n.r*GW+n.c); });
  if(!goals.size) return null;
  const prev=new Map([[start,-1]]), q=[start];
  while(q.length){
    const cur=q.shift();
    if(goals.has(cur)){ const path=[]; let k=cur; while(k!==-1&&k!==start){ path.unshift({c:k%GW,r:Math.floor(k/GW)}); k=prev.get(k); } if(cur===start) path.push({c:sc,r:sr}); return path; }
    const c=cur%GW, r=Math.floor(cur/GW);
    for(const d of DIRS){ const n=tileAt(c+d[0],r+d[1]); if(!n||n.solid) continue; const id=n.r*GW+n.c; if(prev.has(id)||(block.has(id)&&!goals.has(id))) continue; prev.set(id,cur); q.push(id); }
  }
  return null;
}
const S=(tile,act,cond)=>({tile,act,cond,t:null});
function chopSteps(ch,ctx,crate){
  return [S(()=>nearestT(ch,t=>t.k===crate),'use'),
    S(()=>ctx.b&&!ctx.b.item?ctx.b:(ctx.b=reserve(ch,nearestT(ch,t=>t.k==='C'&&!t.item))),'use'),
    S(()=>ctx.b,'chop'), S(()=>ctx.b,'use')];
}
function planFor(ch){
  releaseRes(ch); ch.bot.order=null;
  const h=ch.held;
  if(h){
    if(h.t==='pot'||h.t==='pan'){ const k=h.t==='pot'?'S':'F'; return [S(()=>nearestT(ch,t=>t.k==='X'),'use'),S(()=>nearestT(ch,t=>t.k===k&&!t.item)||nearestT(ch,t=>(t.k==='#'||t.k==='=')&&!t.item),'use')]; }
    return [S(()=>nearestT(ch,t=>t.k==='X'),'use'),S(()=>nearestT(ch,t=>t.k==='P'),'use')].slice(0,h.t==='plate'?2:1);
  }
  const bt=nearestT(ch,t=>(t.k==='S'||t.k==='F')&&t.item&&t.item.burnt);
  if(bt){ reserve(ch,bt); return [S(()=>bt,'use'),S(()=>nearestT(ch,t=>t.k==='X'),'use'),S(()=>bt,'use')]; }
  const taken=new Set(G.chefs.filter(c=>c!==ch&&c.bot&&c.bot.order).map(c=>c.bot.order));
  const o=G.orders.find(x=>x.state==='live'&&!taken.has(x.id)&&x.left>8);
  if(!o) return null;
  ch.bot.order=o.id;
  const ctx={}, P=()=>nearestT(ch,t=>t.k==='P'), W=()=>nearestT(ch,t=>t.k==='W');
  const A=()=>ctx.A||(ctx.A=reserve(ch,nearestT(ch,t=>(t.k==='#'||t.k==='=')&&!t.item)));
  if(o.r==='soup'){
    const pot=nearestT(ch,t=>t.k==='S'&&t.item&&t.item.t==='pot'&&!t.item.burnt&&t.item.n>=3)||nearestT(ch,t=>t.k==='S'&&t.item&&t.item.t==='pot'&&!t.item.burnt);
    if(!pot) return null; reserve(ch,pot);
    const st=[];
    for(let i=pot.item.n;i<3;i++) st.push(...chopSteps(ch,ctx,'T'),S(()=>pot,'use'));
    st.push(S(P,'use'),S(()=>pot,'use',()=>!pot.item||potReady(pot.item)||pot.item.burnt),S(W,'use'));
    return st;
  }
  if(o.r==='salad') return [S(P,'use'),S(A,'use'),...chopSteps(ch,ctx,'L'),S(A,'use'),...chopSteps(ch,ctx,'T'),S(A,'use'),S(A,'use'),S(W,'use')];
  const pan=nearestT(ch,t=>t.k==='F'&&t.item&&t.item.t==='pan'&&!t.item.meat&&!t.item.burnt);
  if(!pan) return null; reserve(ch,pan);
  return [S(P,'use'),S(A,'use'),S(()=>nearestT(ch,t=>t.k==='B'),'use'),S(A,'use'),...chopSteps(ch,ctx,'L'),S(A,'use'),
    ...chopSteps(ch,ctx,'M'),S(()=>pan,'use'),S(A,'use'),S(()=>pan,'use',()=>!pan.item||panReady(pan.item)||pan.item.burnt),S(W,'use')];
}
function botAbort(ch){
  const b=ch.bot; b.steps=null; b.fails=(b.fails||0)+1;
  const h=ch.held;
  if(h&&b.fails>2){
    if(h.t==='pot'||h.t==='pan'){ const t=G.tiles.find(t=>(t.k==='S'||t.k==='F')&&!t.item)||G.tiles.find(t=>t.k==='#'&&!t.item); if(t){ emptyC(h); placeItem(t,takeHeld(ch)); } }
    else destroyItem(takeHeld(ch));
    b.fails=0;
  }
  releaseRes(ch);
}
function botThink(ch,dt){
  const b=ch.bot||(ch.bot={steps:null,i:0,path:null,repath:0,stuck:0,best:1e9,wait:0,order:null,fails:0});
  ch.ai={ix:0,iy:0,chop:false};
  if(!b.steps){ b.steps=planFor(ch); b.i=0; b.path=null; b.wait=0; if(!b.steps) return; }
  const st=b.steps[b.i];
  if(!st){ b.steps=null; releaseRes(ch); b.fails=0; return; }
  if(!st.t) st.t=st.tile();
  const tile=st.t; if(!tile){ botAbort(ch); return; }
  b.repath-=dt;
  if(!b.path||b.repath<=0||b.pathTile!==tile){ b.path=bfsPath(ch,tile)||bfsPath(ch,tile,true); b.pathTile=tile; b.repath=0.5; b.best=1e9; }
  if(!b.path){ botAbort(ch); return; }
  if(b.path.length){
    const cell=b.path[0], tx=OX+cell.c*TS+32, ty=OY+cell.r*TS+34, dx=tx-ch.x, dy=ty-ch.y, d=Math.hypot(dx,dy);
    if(d<(b.path.length>1?16:5)){ b.path.shift(); b.best=1e9; b.stuck=0; }
    else {
      ch.ai.ix=dx/d; ch.ai.iy=dy/d;
      if(d<b.best-0.5){ b.best=d; b.stuck=0; } else b.stuck+=dt;
      if(b.stuck>1.1){ const g=b.path[b.path.length-1]; ch.x=OX+g.c*TS+32; ch.y=OY+g.r*TS+34; ch.vx=ch.vy=0; b.path=[]; b.stuck=0; }
    }
    return;
  }
  const [cc,cr]=cellOf(ch);
  if(Math.abs(tile.c-cc)+Math.abs(tile.r-cr)!==1){ b.path=null; return; }
  ch.fx=tile.c-cc; ch.fy=tile.r-cr; ch.vx*=0.5; ch.vy*=0.5;
  if(st.act==='chop'){ const it=tile.item; if(!it||it.ch||ch.held){ b.i++; b.path=null; } else ch.ai.chop=true; return; }
  if(st.cond&&!st.cond()){ b.wait+=dt; if(b.wait>30) botAbort(ch); return; }
  b.wait=0;
  if(interact(ch)){ b.i++; b.path=null; } else botAbort(ch);
}

// ===== main loop =====
function playUpdate(dt){
  G.time-=dt;
  const two=G.mode===2;
  if(!two&&!G.botOn&&isPressed(MAP1.swap)){ G.active=1-G.active; sfx('swap'); const c=G.chefs[G.active]; c.sq=1; for(let i=0;i<6;i++) fx('spark',c.x+rnd(-16,16),c.y-110+rnd(-8,8)); }
  G.chefs.forEach((ch,i)=>{
    let ix=0,iy=0,pick=false,chop=false,dash=false;
    const bot=G.botOn&&(i===0||G.botOn===2);
    if(bot){ botThink(ch,dt); ix=ch.ai.ix; iy=ch.ai.iy; chop=ch.ai.chop; }
    else if(two||i===G.active){ const m=two?MAP2[i]:MAP1; ix=isHeld(m.right)-isHeld(m.left); iy=isHeld(m.down)-isHeld(m.up); pick=isPressed(m.pick); chop=!!isHeld(m.chop); dash=isPressed(m.dash); }
    chefMove(ch,ix,iy,dash,dt);
    if(pick) interact(ch);
    chopUpdate(ch,chop,dt);
  });
  collideChefs();
  cartUpdate(dt);
  cookUpdate(dt);
  ordersUpdate(dt);
  if(G.time<=10){ const s=Math.ceil(G.time); if(s!==G.lastTick){ G.lastTick=s; if(s>0) sfx('tick'); } }
  if(G.time<=0){ G.time=0; endRound(); }
}
function update(dt){
  G.t+=dt;
  if(G.shake>0) G.shake=Math.max(0,G.shake-dt);
  const s=G.state;
  if(s==='title'||s==='help') titleUpdate(dt);
  else if(s==='countdown'){
    G.cd-=dt;
    const beat=Math.ceil(G.cd/1.3); if(beat<G.cdBeat){ G.cdBeat=beat; sfx(beat<=0?'go':'beep'); }
    G.chefs.forEach(ch=>{ chefMove(ch,0,0,false,dt); });
    cookUpdate(0);
    if(G.cd<=0){ G.state='playing'; show(SCR.count,false); AU.music=true; }
  }
  else if(s==='playing') playUpdate(dt);
  else if(s==='over'){ overUpdate(dt); cookUpdate(0); }
  if(s!=='paused'){ fxUpdate(dt); confUpdate(dt); }
}
let last=performance.now(), wasShake=false;
function render(dt){
  const s=G.state;
  if(G.shake>0){ const a=G.shake*16; mv(L.world,rnd(-a,a),rnd(-a,a)); wasShake=true; }
  else if(wasShake){ L.world.removeAttribute('transform'); wasShake=false; }
  if(s!=='paused') for(const ch of G.chefs) chefAnim(ch,dt);
  G.hi.forEach((g,i)=>{
    const ch=G.chefs[i], on=s==='playing'&&ch&&(G.mode===2||i===G.active||(G.botOn&&i===0));
    const t=on?targetTile(ch):null; show(g,!!t);
    if(t) mv(g,t.cx,t.y+t.th/2,1+Math.sin(G.t*8)*0.035);
  });
  const arr=G.chefs.map(c=>[c.g,c.y]); if(G.cart) arr.push([G.cart.g,G.cart.y+12]);
  arr.sort((a,b)=>a[1]-b[1]);
  if(arr.some((a,i)=>L.actors.childNodes[i]!==a[0])) arr.forEach(a=>L.actors.appendChild(a[0]));
  if(s==='countdown'){
    const ph=G.cd>1.3?0:1, lt=ph?1.3-G.cd:2.6-G.cd;
    UI.cdTxt.textContent=ph?'开工！':'准备…';
    UI.cdTxt.setAttribute('fill',ph?MINT:YEL);
    mv(UI.cdTxt,0,0,1); UI.cdTxt.setAttribute('transform','translate(640,380) scale('+easeOutBack(lt/0.4).toFixed(3)+') translate(-640,-380)');
    mv(UI.cdBan,640,250,easeOutBack((2.6-G.cd)/0.4));
  }
  if(s!=='title'&&s!=='help'){ ticketsRender(dt); hudUpdate(dt); }
}
function frame(now){
  let dt=(now-last)/1000; last=now;
  if(!(dt>0)) dt=0; if(dt>1/30) dt=1/30;
  const n=G.state==='playing'?Math.max(1,Math.min(8,G.speed|0)):1;
  try{
    for(let i=0;i<n;i++){ update(dt); PRESSED.clear(); if(G.state!=='playing') break; }
    render(dt); musicTick();
  }catch(err){ console.warn(err); }
  requestAnimationFrame(frame);
}

// ===== test hook =====
function giveSpec(spec){
  const [k,rest]=spec.split(':');
  const base={tom:['tom',false],tomC:['tom',true],let:['let',false],letC:['let',true],meat:['meat',false],meatC:['meat',true],bun:['bun',false]};
  if(base[k]) return mkItem(base[k][0],{ch:base[k][1]});
  if(k==='plate') return mkItem('plate',{parts:rest?rest.split(','):[]});
  if(k==='pot') return mkItem('pot',{n:rest?+rest:0});
  if(k==='pan') return mkItem('pan',{meat:!!rest,cook:rest==='done'?1:0});
  return null;
}
window.__GAME__={
  get state(){ return G.state; },
  get score(){ return G.score; },
  start(diff){ startGame(clamp((diff|0),0,2),false); return G.state; },
  debug:{
    tp(i,c,r,dir){ const ch=G.chefs[i]; ch.x=OX+c*TS+32; ch.y=OY+r*TS+34; ch.vx=ch.vy=0; const d={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[dir||'down']; ch.fx=d[0]; ch.fy=d[1]; return [ch.x,ch.y]; },
    give(i,spec){ const ch=G.chefs[i]; if(ch.held) destroyItem(takeHeld(ch)); const it=giveSpec(spec); if(it) setHeld(ch,it); return !!it; },
    held(i){ const h=G.chefs[i].held; return h?{t:h.t,ch:h.ch,parts:h.parts.slice(),n:h.n,cook:+h.cook.toFixed(2),meat:h.meat,burnt:h.burnt}:null; },
    target(i){ const t=targetTile(G.chefs[i]); return t?{c:t.c,r:t.r,k:t.k,item:t.item?t.item.t:null}:null; },
    tileItem(c,r){ const t=tileAt(c,r), it=t&&t.item; return it?{t:it.t,ch:it.ch,prog:+it.prog.toFixed(2),parts:it.parts.slice(),n:it.n,cook:+it.cook.toFixed(2),over:+it.over.toFixed(2),meat:it.meat,burnt:it.burnt}:null; },
    ff(sec){ for(let s=0;s<sec;s+=0.05) cookUpdate(0.05); return true; },
    order(r){ const lv=G.lvl, keep=lv.recipes; lv.recipes=[r]; spawnOrder(); lv.recipes=keep; return G.orders.length; },
    orders(){ return G.orders.filter(o=>o.state==='live').map(o=>({r:o.r,left:+o.left.toFixed(1)})); },
    bot(n){ G.botOn=n|0; RES.clear(); G.chefs.forEach(c=>{ c.bot=null; c.ai=null; }); return G.botOn; },
    speed(x){ G.speed=x; return x; },
    setTime(t){ G.time=t; return t; },
    setScore(s){ G.score=s; G.shown=s; return s; },
    stats(){ return Object.assign({time:+G.time.toFixed(1),score:G.score,mode:G.mode,level:G.li,active:G.active},G.stats); },
    mode(m){ G.mode=m; if(G.state==='title') refreshTitle(); return m; },
    chefs(){ return G.chefs.map(c=>({x:Math.round(c.x),y:Math.round(c.y),held:c.held?c.held.t:null,cell:cellOf(c)})); },
    find(k){ return G.tiles.filter(t=>t.k===k).map(t=>[t.c,t.r]); },
    nodes(){ return document.getElementsByTagName('*').length; }
  }
};

// ===== init =====
buildHud(); initFx(); buildTitle(); buildHelp(); buildPause(); buildOver(); buildCount(); buildTop();
show(HUD,false);
toTitle();
requestAnimationFrame(t=>{ last=t; requestAnimationFrame(frame); });
})();
